:root { --demo: #0ea5e9; }

.wz {
  display: grid; gap: 28px; padding: 28px;
  grid-template-columns: 200px 1fr 220px;
  align-items: start;
}
@media (max-width: 900px) { .wz { grid-template-columns: 1fr; } .wz-preview { justify-self: center; } }

/* --- trilha --- */
.wz-passos { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 18px; }
.wz-passo { display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--text-dim); }
.wz-bola {
  width: 20px; height: 20px; flex-shrink: 0;
  border: 1px solid var(--border-alt); border-radius: 100px;
  display: grid; place-items: center; font-size: 11px;
}
.wz-passo.wz-feito .wz-bola { background: var(--demo); border-color: var(--demo); color: #fff; }
.wz-passo.wz-feito .wz-bola::after { content: '✓'; }
.wz-passo.wz-feito .wz-rotulo { text-decoration: line-through; }
.wz-passo.wz-atual .wz-bola { border-color: var(--demo); }
.wz-passo.wz-atual { color: var(--text); font-weight: 600; }

/* --- painel --- */
.wz-painel { min-height: 300px; display: flex; flex-direction: column; }
.wz-tela { display: none; }
.wz-tela.wz-ativa { display: block; }
.wz-tela h2 { margin: 0 0 8px; font-family: 'Sora', sans-serif; font-size: 19px; }
.wz-tela p { margin: 0 0 14px; color: var(--text-muted); line-height: 1.6; }
.wz-nota { font-size: 12px; }
.wz-nota code { font-family: 'JetBrains Mono', monospace; color: var(--accent); }

.wz-campo { display: flex; flex-direction: column; gap: 6px; max-width: 320px; }
.wz-campo span { font-size: 12px; color: var(--text-muted); }
.wz-campo input {
  padding: 10px 12px; border: 1px solid var(--border); border-radius: 8px;
  background: var(--bg); color: var(--text); font-family: inherit; font-size: 14px;
}

.wz-link {
  border: none; background: none; padding: 0; cursor: pointer;
  color: var(--demo); font: inherit; text-decoration: underline;
}
/* Escondido mas clicável pelo link: o seletor nativo abre no clique
   programático e não precisa de estilo próprio. */
#wz-cor { position: absolute; opacity: 0; width: 1px; height: 1px; pointer-events: none; }

.wz-acoes { display: flex; gap: 10px; margin-top: auto; padding-top: 24px; }
.wz-btn {
  padding: 10px 20px; border-radius: 8px; font: inherit; font-size: 13px; font-weight: 600;
  cursor: pointer; border: 1px solid var(--border); background: transparent; color: var(--text-muted);
}
.wz-principal { background: var(--demo); border-color: transparent; color: #fff; }
.wz-acoes.wz-fim { display: none; }

/* --- maquete de celular --- */
.wz-celular {
  position: relative; width: 200px; height: 340px;
  border: 6px solid var(--border-alt); border-radius: 26px; overflow: hidden;
  background: var(--bg);
}
.wz-celular::before {
  content: ''; position: absolute; top: 0; left: 50%; transform: translateX(-50%);
  width: 70px; height: 14px; border-radius: 0 0 10px 10px; background: var(--border-alt); z-index: 2;
}

/* Tudo aqui lê a mesma variável: trocar --demo repinta o conjunto sem que o
   JavaScript toque num único nó. */
.wz-topo {
  background: var(--demo); color: #fff;
  padding: 26px 14px 12px; font-size: 13px; font-weight: 700; text-align: center;
}
.wz-corpo { padding: 16px 14px; display: flex; flex-direction: column; gap: 10px; }
.wz-selo {
  align-self: flex-start; padding: 3px 10px; border-radius: 100px;
  background: var(--demo); color: #fff; font-size: 10px; font-weight: 700;
}
.wz-linha { height: 10px; border-radius: 4px; background: var(--border-alt); }
.wz-curta { width: 60%; }
.wz-cta {
  margin-top: auto; padding: 10px; border: none; border-radius: 8px;
  background: var(--demo); color: #fff; font: inherit; font-size: 12px; font-weight: 600;
}

