export function iniciarWizard(raiz) {
  const telas = [...raiz.querySelectorAll('.wz-tela')]
  const passos = [...raiz.querySelectorAll('.wz-passo')]
  const acoes = raiz.querySelector('.wz-acoes')
  const voltar = raiz.querySelector('.wz-voltar')
  const principal = raiz.querySelector('.wz-principal')
  let i = 0

  function render() {
    telas.forEach((t, n) => t.classList.toggle('wz-ativa', n === i))
    passos.forEach((p, n) => {
      p.classList.toggle('wz-feito', n < i)
      p.classList.toggle('wz-atual', n === i)
    })

    // O rótulo diz onde a pessoa está. Botão que repete "Avançar" até o fim
    // esconde dela quantos passos faltam.
    principal.textContent = i === telas.length - 2 ? 'Concluir' : 'Avançar'
    voltar.disabled = i === 0
    // Na última tela não há mais passo nem para onde voltar.
    acoes.classList.toggle('wz-fim', i === telas.length - 1)
  }

  principal.addEventListener('click', () => { if (i < telas.length - 1) { i++; render() } })
  voltar.addEventListener('click', () => { if (i > 0) { i--; render() } })

  // O preview inteiro depende de --demo. Uma linha aqui, e topo, selo e botão
  // repintam pela cascata — nenhum nó é percorrido.
  const cor = raiz.querySelector('#wz-cor')
  raiz.querySelector('#wz-abrir').addEventListener('click', () => cor.click())
  cor.addEventListener('input', () => {
    document.documentElement.style.setProperty('--demo', cor.value)
  })

  render()
}
